is_creative = any(k in task_0.lower() for k in ["write a proposal","draft a report","generate a report","write a summary","create a document","write a letter","write an essay"])

def parse_date(s):
    s = (s or "").strip()
    # ISO
    if len(s) >= 10 and len(s) >= 5 and s[4] == "-":
        try:
            return datetime.datetime.strptime(s[:10], "%Y-%m-%d")
        except:
            pass
    for fmt in ["%b %d, %Y", "%m/%d/%Y", "%d/%m/%Y", "%B %d, %Y"]:
        try:
            return datetime.datetime.strptime(s, fmt)
        except:
            pass
    return None

def month_year_label(dt):
    # Month name + year
    return dt.strftime("%B %Y")

def extract_records(text):
    sample = text[:5000]
    if "||" in sample: delim = "||"
    elif "\t" in sample and sample.count("\t") > sample.count("|"): delim = "\t"
    elif "|" in sample: delim = "|"
    else: delim = ","
    lines = [l for l in text.splitlines() if delim in l and "Label:" in l and "Date:" in l]
    records = []
    for line in lines:
        rec = {}
        for part in line.split(delim):
            if ":" in part:
                k, v = part.split(":", 1)
                rec[k.strip().lower()] = v.strip()
        if rec:
            records.append(rec)
    return records

def compute_answer_from_records(records):
    # Aggregate by month-year
    month_counts = collections.defaultdict(lambda: collections.Counter())
    month_dt = {}  # keep representative dt for sorting
    for r in records:
        dt = parse_date(r.get("date", ""))
        lab = (r.get("label", "") or "").strip().lower()
        if not dt or lab not in ("correct", "incorrect"):
            continue
        key = dt.strftime("%Y-%m")
        month_counts[key][lab] += 1
        month_dt[key] = datetime.datetime(dt.year, dt.month, 1)

    if not month_counts:
        return None

    # Find earliest month where incorrect > correct
    earliest_key = None
    for key in sorted(month_counts.keys(), key=lambda k: month_dt.get(k, datetime.datetime.max)):
        c = month_counts[key].get("correct", 0)
        ic = month_counts[key].get("incorrect", 0)
        if ic > c:
            earliest_key = key
            break

    if earliest_key is None:
        return None

    dt0 = month_dt[earliest_key]
    return f"Answer: {month_year_label(dt0)}"

