```python
# REASONING: Build a stdlib-only pipeline that can (1) extract text from a .docx (ZIP+XML), (2) parse patient/monthly labs into structured records, (3) apply standing-order rules to generate monthly medication/treatment actions, and (4) write those results into an .xlsx template (also ZIP+XML) without external libraries.
import re, json, datetime, collections   # MANDATORY first code line
from xml.etree import ElementTree as ET
from zipfile import ZipFile
from io import BytesIO

# ----------------------------
# Utilities: DOCX (Word) parsing (stdlib-only)
# ----------------------------

_W_NS = {
    "w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
}

def _docx_extract_paragraph_texts(docx_bytes: bytes):
    """Return list of paragraph texts from word/document.xml."""
    with ZipFile(BytesIO(docx_bytes), "r") as z:
        xml = z.read("word/document.xml")
    root = ET.fromstring(xml)
    paras = []
    for p in root.findall(".//w:p", _W_NS):
        texts = []
        for t in p.findall(".//w:t", _W_NS):
            if t.text:
                texts.append(t.text)
        s = "".join(texts).strip()
        if s:
            paras.append(s)
    return paras

def docx_to_text(docx_bytes: bytes) -> str:
    """Flatten paragraphs to a single text blob; preserves ordering."""
    paras = _docx_extract_paragraph_texts(docx_bytes)
    return "\n".join(paras)

# ----------------------------
# Parsing: Patient Lab Reports (heuristic / regex-driven)
# ----------------------------

MONTHS = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"]

def _norm_month(s: str):
    s = s.strip()
    # Accept formats like "January", "Jan", "JAN", "01/2025", "2025-01", etc.
    m = re.search(r'\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\b', s, re.I)
    if m:
        abbr = m.group(1)[:3].upper()
        return abbr
    m2 = re.search(r'\b(20\d{2})[-/](\d{1,2})\b', s)
    if m2:
        year = int(m2.group(1))
        month = int(m2.group(2))
        if 1 <= month <= 12:
            return MONTHS[month-1]
    m3 = re.search(r'\b(\d{1,2})/(\d{4})\b', s)
    if m3:
        month = int(m3.group(1))
        if 1 <= month <= 12:
            return MONTHS[month-1]
    return None

def parse_patient_lab_reports(text_blob: str):
    """
    Parse lab reports into:
      patients[name] = {"mrn": str, "months": {MON: {lab: value,...}}, "provider": str}
    This is intentionally heuristic because real lab report formatting varies.
    """
    # Split into patient sections (common patterns: "Patient:", "Name:", "MRN:", all-caps headers, etc.)
    # We anchor on MRN occurrences to segment.
    lines = [ln.strip() for ln in text_blob.splitlines() if ln.strip()]
    joined = "\n".join(lines)

    # Try to find patient headers: "Patient Name: X", "Name: X", etc.
    # We segment by "MRN" occurrences.
    mrn_iter = list(re.finditer(r'\bMRN\b\s*[:#]?\s*(\d+)\b', joined, re.I))
    if not mrn_iter:
        return {}

    # Define section boundaries around each MRN match
    sections = []
    for i, m in enumerate(mrn_iter):
        start = m.start()
        end = mrn_iter[i+1].start() if i+1 < len(mrn_iter) else len(joined)
        sections.append(joined[max(0, start-300):end])

    patients = {}
    for sec in sections:
        mrn_m = re.search(r'\bMRN\b\s*[:#]?\s*(\d+)\b', sec, re.I)
        mrn = mrn_m.group(1) if mrn_m else ""

        # Name: prefer explicit "Patient:"/ "Name:"; fallback: a line before MRN with letters/spaces
        name = None
        nm = re.search(r'\b(?:Patient\s*Name|Patient|Name)\b\s*[:#]?\s*([A-Za-z][A-Za-z\'\-\. ]+)', sec, re.I)
        if nm:
            name = nm.group(1).strip()
        else:
            # fallback: take text just before MRN on same/previous line
            pre = sec[:mrn_m.start()] if mrn_m else sec
            pre_lines = [x.strip() for x in pre.splitlines() if x.strip()]
            if pre_lines:
                cand = pre_lines[-1]
                # Remove labels if present
                cand = re.sub(r'\b(?:Patient|Name)\b\s*[:#]?\s*', '', cand, flags=re.I).strip()
                if re.fullmatch(r"[A-Za-z][A-Za-z'\-\. ]+", cand):
                    name = cand

        if not name:
            continue

        # Parse monthly labs: find month headings and then key:value pairs until next month
        # Labs we care about (can expand):
        lab_keys = [
            "KT/V", "KT/V (sp)", "Kt/V", "HGB", "Hemoglobin",
            "Ferritin", "TSAT", "Transferrin Saturation",
            "Calcium", "Ca", "Phosphorus", "Phos", "PTH",
            "Albumin", "Alb", "Potassium", "K", "Bicarbonate", "CO2"
        ]

        # Build a tokenizable view
        sec_lines = [ln.strip() for ln in sec.splitlines() if ln.strip()]
        # Identify month markers by scanning lines
        month_positions = []
        for idx, ln in enumerate(sec_lines):
            mon = _norm_month(ln)
            if mon:
                month_positions.append((idx, mon))
        month_positions = month_positions or []

        months = collections.OrderedDict()
        if month_positions:
            for i, (idx, mon) in enumerate(month_positions):
                end = month_positions[i+1][0] if i+1 < len(month_positions) else len(sec_lines)
                block = "\n".join(sec_lines[idx:end])
                months[mon] = _parse_labs_from_block(block)
        else:
            # If no explicit month headings, attempt to parse any "MON - lab: value" style
            months = _parse_month_inline(sec)

        patients[name] = {"mrn": mrn, "months": dict(months)}

    return patients

def _parse_labs_from_block(block: str):
    """
    Extract lab numeric values from a month block.
    Accept patterns like:
      "KT/V: 1.15", "HGB 9.8", "Calcium 8.1", "Phosphorus: 6.2 mg/dL"
    """
    labs = {}
    # Common lab label normalization
    lab_alias = {
        "hemoglobin": "hgb",
        "hgb": "hgb",
        "kt/v": "ktv",
        "k t/v": "ktv",
        "calcium": "calcium",
        "ca": "calcium",
        "phosphorus": "phosphorus",
        "phos": "phosphorus",
        "albumin": "albumin",
        "alb": "albumin",
        "ferritin": "ferritin",
        "tsat": "tsat",
        "transferrin saturation": "tsat",
        "pth": "pth",
    }

    # Find patterns "Label ... number"
    # Note: Do not use \d{1,N}; rule says \d+
    for m in re.finditer(r'([A-Za-z][A-Za-z/ \-]+?)\s*[:=]?\s*([-+]?\d+(?:\.\d+)?)', block):
        raw_label = re.sub(r'\s+', ' ', m.group(1)).strip().lower()
        val = float(m.group(2))
        # collapse label variants
        raw_label = raw_label.replace("k t/v", "kt/v")
        raw_label = raw_label.replace("kt/v (sp)", "kt/v")
        raw_label = raw_label.strip(" -")
        if raw_label in lab_alias:
            labs[lab_alias[raw_label]] = val
        else:
            # try partial known labels
            for k in lab_alias:
                if raw_label == k:
                    labs[lab_alias[k]] = val
                    break
    return labs

def _parse_month_inline(sec: str):
    """Fallback: parse month inline records if present."""
    months = collections.OrderedDict()
    for mon in MONTHS:
        # look for "JAN ...", "Jan ...", etc.
        hits = list(re.finditer(r'\b' + mon + r'\b', sec, re.I))
        if not hits:
            continue
        # take around first hit
        h = hits[0]
        window = sec[max(0, h.start()-200): h.start()+800]
        months[mon] = _parse_labs_from_block(window)
    return months

# ----------------------------
# Standing orders: monthly medication/treatment changes
# ----------------------------

def determine_provider(patient_name: str):
    """
    Provider mapping from task statement.
    """
    dr_joe = {"Cash Stonewater", "Fred Fintmore"}
    dr_johnson = {"Betty Brite", "Tina Lee Bell"}
    dr_lee = {"Eric Bird", "Homer Sandson"}
    dr_michael = {"Jessica Rashmore"}

    if patient_name in dr_joe:
        return "Dr. Joe"
    if patient_name in dr_johnson:
        return "Dr. Johnson"
    if patient_name in dr_lee:
        return "Dr. Lee"
    if patient_name in dr_michael:
        return "Dr. Michael"
    return "Unknown"

def apply_monthly_protocols(patients: dict):
    """
    For each patient+month, compute orders/changes based on the rules in task.
    Returns: patients dict augmented with 'provider' and 'actions' per month.
    """
    # Persistent med state per patient (carry forward month-to-month)
    # We'll process months in calendar order JAN..DEC if present.
    out = {}
    for name, pdata in patients.items():
        provider = determine_provider(name)
        mrn = pdata.get("mrn", "")
        months = pdata.get("months", {})
        # initialize med state
        state = {
            "aranesp": None,   # None or "10 mcg IVP each treatment" or "10 mcg IVP two times a week"
            "renvela": 0,      # tablets per meal (0..4)
            "phoslo": 0,       # tablets per meal (0..)
            "tums": False,     # on/off
        }

        # determine month iteration order
        present = [m for m in MONTHS if m in months]
        actions_by_month = collections.OrderedDict()
        for mon in present:
            labs = months.get(mon, {})
            actions = []

            # Adequacy: repeat labs if KT/V < 1.2
            ktv = labs.get("ktv")
            if ktv is not None and ktv < 1.2:
                actions.append("Order: Repeat adequacy/lab work in 1 month (KT/V < 1.2).")

            # Calcium: TUMS if 7.9-8.4 inclusive
            ca = labs.get("calcium")
            if ca is not None and 7.9 <= ca <= 8.4:
                if not state["tums"]:
                    state["tums"] = True
                    actions.append("Start: TUMS 2 tabs PO three times weekly (Ca 7.9-8.4).")
                else:
                    actions.append("Continue: TUMS 2 tabs PO three times weekly (Ca 7.9-8.4).")
            # No explicit stop rule given; keep as-is otherwise.

            # Anemia: Aranesp start if HGB < 10.0
            hgb = labs.get("hgb")
            if hgb is not None and hgb < 10.0:
                if state["aranesp"] is None:
                    state["aranesp"] = "10 mcg IVP each treatment"
                    actions.append("Start: Aranesp 10 mcg IVP each treatment (HGB < 10.0).")
                else:
                    actions.append(f"Continue: Aranesp ({state['aranesp']}) (HGB < 10.0).")
            # Note: Dose-decrease per standing protocol table is referenced but table values are not in task text.
            # We include a placeholder decision hook based on HGB recovery above target.
            if hgb is not None and state["aranesp"] == "10 mcg IVP each treatment" and hgb >= 11.0:
                # Heuristic: decrease if HGB rises; actual thresholds should come from the Aranesp protocol table.
                state["aranesp"] = "10 mcg IVP two times a week"
                actions.append("Decrease: Aranesp to 10 mcg IVP two times weekly (per standing protocol dose-decrease).")

            # Phosphorus binders depend on provider group
            phos = labs.get("phosphorus")
            if phos is not None:
                if provider in ("Dr. Joe", "Dr. Johnson"):
                    # Renvela initiation if 5.6-7.4
                    if 5.6 <= phos <= 7.4:
                        if state["renvela"] == 0:
                            state["renvela"] = 1
                            actions.append("Start: Renvela 800 mg PO with meals (1 tab/meal) (Phos 5.6-7.4).")
                        else:
                            # titrate by 1 tab/meal every 2 weeks up to 4; monthly view: allow +1 if still high
                            if state["renvela"] < 4:
                                state["renvela"] += 1
                                actions.append(f"Titrate: Renvela +800 mg per meal (now {state['renvela']} tabs/meal) (still elevated phosphorus).")
                            else:
                                actions.append("Continue: Renvela at max 4 tabs/meal (still elevated phosphorus).")
                    elif 4.0 <= phos <= 5.5:
                        if state["renvela"] > 0:
                            actions.append(f"Continue: Renvela at {state['renvela']} tabs/meal (Phos 4.0-5.5).")
                    # No explicit stop rule if <4.0; leave unchanged.
                elif provider in ("Dr. Michael", "Dr. Lee"):
                    # Phoslo initiation if 5.5-7.4
                    if 5.5 <= phos <= 7.4:
                        if state["phoslo"] == 0:
                            state["phoslo"] = 2
                            actions.append("Start: Phoslo 667 mg, 2 tabs PO with each meal (Phos 5.5-7.4).")
                        else:
                            # Increase by 1 tab/meal monthly if still high (proxy for q2wk titration)
                            state["phoslo"] += 1
                            actions.append(f"Titrate: Phoslo +667 mg per meal (now {state['phoslo']} tabs/meal) (still elevated phosphorus).")
                    elif 4.0 <= phos <= 5.5:
                        if state["phoslo"] > 0:
                            actions.append(f"Continue: Phoslo at {state['phoslo']} tabs/meal (Phos 4.0-5.5).")

            actions_by_month[mon] = {
                "labs": labs,
                "actions": actions,
                "med_state": dict(state),
            }

        out[name] = {
            "mrn": mrn,
            "provider": provider,
            "months": actions_by_month,
        }
    return out

# ----------------------------
# XLSX writing (stdlib-only, XML-based)
# ----------------------------

_S_NS = {
    "main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "rel": "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
}

def _xlsx_list_sheets(xlsx_bytes: bytes):
    """Return list of (sheet_name, sheet_path)."""
    with ZipFile(BytesIO(xlsx_bytes), "r") as z:
        wb = ET.fromstring(z.read("xl/workbook.xml"))
        rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rId_to_target = {}
        for rel in rels.findall(".//{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
            rId_to_target[rel.attrib.get("Id")] = "xl/" + rel.attrib.get("Target").lstrip("/")
        sheets = []
        for sh in wb.findall(".//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet"):
            nm = sh.attrib.get("name")
            rid = sh.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
            target = rId_to_target.get(rid)
            if nm and target:
                sheets.append((nm, target))
        return sheets

def _xlsx_read_shared_strings(z: ZipFile):
    """Return list of shared strings (if present)."""
    try:
        xml = z.read("xl/sharedStrings.xml")
    except KeyError:
        return []
    root = ET.fromstring(xml)
    strings = []
    for si in root.findall(".//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}si"):
        # concatenate all t nodes
        parts = []
        for t in si.findall(".//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"):
            if t.text:
                parts.append(t.text)
        strings.append("".join(parts))
    return strings

def _xlsx_write_shared_strings(z_in: ZipFile, new_strings):
    """Return sharedStrings.xml bytes for the provided list."""
    root = ET.Element("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sst", {
        "xmlns": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
        "count": str(len(new_strings)),
        "uniqueCount": str(len(new_strings)),
    })
    for s in new_strings:
        si = ET.SubElement(root, "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}si")
        t = ET.SubElement(si, "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")
        t.text = s
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)

def _col_to_num(col: str) -> int:
    n = 0
    for ch in col:
        if not ("A" <= ch <= "Z"):
            continue
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n

def _num_to_col(n: int) -> str:
    s = ""
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(ord("A") + r) + s
    return s or "A"

def _cell_ref(col: int, row: int) -> str:
    return f"{_num_to_col(col)}{row}"

def _ensure_row(sheet_root, row_idx: int):
    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    sheetData = sheet_root.find(f".//{{{ns}}}sheetData")
    if sheetData is None:
        sheetData = ET.SubElement(sheet_root, f"{{{ns}}}sheetData")
    # find row
    for r in sheetData.findall(f"{{{ns}}}row"):
        if int(r.attrib.get("r", "0")) == row_idx:
            return r
    r = ET.SubElement(sheetData, f"{{{ns}}}row", {"r": str(row_idx)})
    return r

def _set_cell_string(sheet_root, shared_strings, col: int, row: int, value: str):
    """
    Set a cell to a shared-string value, adding to shared strings if needed.
    Returns possibly-updated shared_strings list.
    """
    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    row_el = _ensure_row(sheet_root, row)
    ref = _cell_ref(col, row)
    # find cell
    c = None
    for cell in row_el.findall(f"{{{ns}}}c"):
        if cell.attrib.get("r") == ref:
            c = cell
            break
    if c is None:
        c = ET.SubElement(row_el, f"{{{ns}}}c", {"r": ref})
    c.attrib["t"] = "s"
    if value not in shared_strings:
        shared_strings.append(value)
    idx = shared_strings.index(value)
    v = c.find(f"{{{ns}}}v")
    if v is None:
        v = ET.SubElement(c, f"{{{ns}}}v")
    v.text = str(idx)
    return shared_strings

def _set_cell_number(sheet_root, col: int, row: int, value):
    """Set numeric cell value (inline number)."""
    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    row_el = _ensure_row(sheet_root, row)
    ref = _cell_ref(col, row)
    c = None
    for cell in row_el.findall(f"{{{ns}}}c"):
        if cell.attrib.get("r") == ref:
            c = cell
            break
    if c is None:
        c = ET.SubElement(row_el, f"{{{ns}}}c", {"r": ref})
    if "t" in c.attrib:
        del c.attrib["t"]
    v = c.find(f"{{{ns}}}v")
    if v is None:
        v = ET.SubElement(c, f"{{{ns}}}v")
    v.text = str(value)

def populate_monthly_tracker_xlsx(xlsx_bytes: bytes, patient_data: dict):
    """
    Populate an XLSX template (Monthly Tracker- Patient Lab Results).
    Because templates vary, this function uses a conservative approach:
      - It writes a simple tabular export to the FIRST sheet:
        Columns: Provider, Patient, MRN, Month, Kt/V, Hgb, Calcium, Phosphorus, Actions
    Returns updated XLSX bytes.
    """
    bio_in = BytesIO(xlsx_bytes)
    bio_out = BytesIO()
    with ZipFile(bio_in, "r") as zin, ZipFile(bio_out, "w") as zout:
        # Read shared strings (optional)
        shared = _xlsx_read_shared_strings(zin)

        sheets = _xlsx_list_sheets(xlsx_bytes)
        if not sheets:
            # copy through unchanged
            for info in zin.infolist():
                zout.writestr(info, zin.read(info.filename))
            return bio_out.getvalue()

        sheet_name, sheet_path = sheets[0]
        sheet_xml = zin.read(sheet_path)
        sheet_root = ET.fromstring(sheet_xml)

        # Write header row at row 1
        headers = ["Provider", "Patient", "MRN", "Month", "Kt/V", "Hgb", "Calcium", "Phosphorus", "Actions"]
        row = 1
        for ci, h in enumerate(headers, start=1):
            shared = _set_cell_string(sheet_root, shared, ci, row, h)

        # Data rows
        row = 2
        for patient_name in sorted(patient_data.keys()):
            p = patient_data[patient_name]
            provider = p.get("provider", "")
            mrn = p.get("mrn", "")
            months = p.get("months", {})
            for mon in MONTHS:
                if mon not in months:
                    continue
                entry = months[mon]
                labs = entry.get("labs", {})
                actions = entry.get("actions", [])
                shared = _set_cell_string(sheet_root, shared, 1, row, provider)
                shared = _set_cell_string(sheet_root, shared, 2, row, patient_name)
                shared = _set_cell_string(sheet_root, shared, 3, row, str(mrn))
                shared = _set_cell_string(sheet_root, shared, 4, row, mon)

                # numeric cells if present
                if "ktv" in labs: _set_cell_number(sheet_root, 5, row, labs["ktv"])
                if "hgb" in labs: _set_cell_number(sheet_root, 6, row, labs["hgb"])
                if "calcium" in labs: _set_cell_number(sheet_root, 7, row, labs["calcium"])
                if "phosphorus" in labs: _set_cell_number(sheet_root, 8, row, labs["phosphorus"])

                shared = _set_cell_string(sheet_root, shared, 9, row, " | ".join(actions))
                row += 1

        # Serialize updated sheet
        updated_sheet_xml = ET.tostring(sheet_root, encoding="utf-8", xml_declaration=True)

        # Write everything back, replacing sheet + sharedStrings if present/needed
        for info in zin.infolist():
            fn = info.filename
            if fn == sheet_path:
                zout.writestr(info, updated_sheet_xml)
            elif fn == "xl/sharedStrings.xml":
                zout.writestr(info, _xlsx_write_shared_strings(zin, shared))
            else:
                zout.writestr(info, zin.read(fn))

        # If there was no sharedStrings.xml but we used shared strings, we should add it and update relationships.
        # Many templates already include sharedStrings.xml; implementing full rel updates is beyond minimal scope.
        # If missing, prefer inline strings instead (not implemented here).
    return bio_out.getvalue()

# ----------------------------
# Orchestration
# ----------------------------

def process_lab_reports_and_tracker(docx_bytes: bytes, xlsx_bytes: bytes):
    """
    End-to-end:
      1) Extract text from Patient Lab Reports.docx
      2) Parse patient labs
      3) Apply monthly standing orders
      4) Populate Monthly Tracker xlsx
    Returns: (updated_xlsx_bytes, parsed_json_str)
    """
    text = docx_to_text(docx_bytes)
    patients = parse_patient_lab_reports(text)

    # Add provider mapping for known patients (ensures correct binder rules)
    for nm in list(patients.keys()):
        patients[nm]["provider"] = determine_provider(nm)

    computed = apply_monthly_protocols(patients)
    updated_xlsx = populate_monthly_tracker_xlsx(xlsx_bytes, computed)
    return updated_xlsx, json.dumps(computed, indent=2)

# ----------------------------
