#!/usr/bin/env python3
"""
Populate 'Monthly Tracker- Patient Lab Results.xlsx' using 'Patient Lab Reports.docx'
and apply standing-order protocol-driven monthly medication/treatment changes.

USAGE:
  python fill_monthly_tracker.py --lab_docx "Patient Lab Reports.docx" \
    --tracker_xlsx "Monthly Tracker- Patient Lab Results.xlsx" \
    --out_xlsx "Monthly Tracker- Patient Lab Results.FILLED.xlsx"

NOTES:
- Stdlib only: parses DOCX/XLSX as ZIPs containing XML.
- Because DOCX/XLSX templates can differ, header detection is heuristic and can be tuned
  in HEADER_ALIASES.
"""
import argparse
import datetime as _dt
import re
import zipfile
import xml.etree.ElementTree as ET
from copy import deepcopy

# -----------------------------
# DOCX extraction (stdlib)
# -----------------------------
WORD_NS = {
    "w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
}

def docx_to_text(docx_path: str) -> str:
    with zipfile.ZipFile(docx_path, "r") as z:
        xml = z.read("word/document.xml")
    root = ET.fromstring(xml)
    parts = []
    for p in root.findall(".//w:p", WORD_NS):
        texts = []
        for t in p.findall(".//w:t", WORD_NS):
            if t.text:
                texts.append(t.text)
        line = "".join(texts).strip()
        if line:
            parts.append(line)
    return "\n".join(parts)

# -----------------------------
# XLSX read/write (stdlib)
# Minimal cell update using inline strings to avoid sharedStrings complexity.
# -----------------------------
XLSX_NS = {
    "s": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "rel": "http://schemas.openxmlformats.org/package/2006/relationships",
    "p": "http://schemas.openxmlformats.org/package/2006/content-types",
}

def col_to_num(col: str) -> int:
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch.upper()) - 64)
    return n

def num_to_col(n: int) -> str:
    s = ""
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s

_cell_ref_re = re.compile(r"^([A-Z]+)(\d+)$")

def split_cell_ref(a1: str):
    m = _cell_ref_re.match(a1.upper())
    if not m:
        raise ValueError(f"Bad cell ref: {a1}")
    return m.group(1), int(m.group(2))

def _get_first_sheet_path(z: zipfile.ZipFile) -> str:
    # workbook.xml -> sheet r:id -> workbook.xml.rels -> target
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb.findall(".//s:sheets/s:sheet", XLSX_NS)
    if not sheets:
        raise ValueError("No sheets found in workbook.xml")
    rid = sheets[0].attrib.get(f"{{{XLSX_NS['r']}}}id")
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    for rel in rels.findall(".//rel:Relationship", XLSX_NS):
        if rel.attrib.get("Id") == rid:
            target = rel.attrib.get("Target")
            # target like 'worksheets/sheet1.xml'
            return "xl/" + target.lstrip("/")
    raise ValueError("Could not resolve first worksheet target")

def _find_row(sheet_root, row_num: int):
    for row in sheet_root.findall(".//s:sheetData/s:row", XLSX_NS):
        if int(row.attrib.get("r", "0")) == row_num:
            return row
    return None

def _find_cell(row_el, a1: str):
    for c in row_el.findall("s:c", XLSX_NS):
        if c.attrib.get("r") == a1:
            return c
    return None

def _ensure_row(sheet_root, row_num: int):
    sheetData = sheet_root.find(".//s:sheetData", XLSX_NS)
    if sheetData is None:
        sheetData = ET.SubElement(sheet_root, f"{{{XLSX_NS['s']}}}sheetData")
    row = _find_row(sheet_root, row_num)
    if row is None:
        row = ET.Element(f"{{{XLSX_NS['s']}}}row", {"r": str(row_num)})
        # insert in order by row number
        inserted = False
        for i, existing in enumerate(list(sheetData)):
            er = int(existing.attrib.get("r", "0"))
            if er > row_num:
                sheetData.insert(i, row)
                inserted = True
                break
        if not inserted:
            sheetData.append(row)
    return row

def _ensure_cell(sheet_root, row_el, col_letters: str, row_num: int):
    a1 = f"{col_letters}{row_num}"
    cell = _find_cell(row_el, a1)
    if cell is None:
        cell = ET.Element(f"{{{XLSX_NS['s']}}}c", {"r": a1})
        # insert in order by column index
        target_idx = col_to_num(col_letters)
        inserted = False
        for i, existing in enumerate(list(row_el)):
            ref = existing.attrib.get("r", "")
            if ref:
                ccol, _ = split_cell_ref(ref)
                if col_to_num(ccol) > target_idx:
                    row_el.insert(i, cell)
                    inserted = True
                    break
        if not inserted:
            row_el.append(cell)
    return cell

def set_cell_inline_str(sheet_root, row_num: int, col_letters: str, text: str):
    row = _ensure_row(sheet_root, row_num)
    cell = _ensure_cell(sheet_root, row, col_letters, row_num)
    # clear children
    for child in list(cell):
        cell.remove(child)
    cell.attrib["t"] = "inlineStr"
    is_el = ET.SubElement(cell, f"{{{XLSX_NS['s']}}}is")
    t_el = ET.SubElement(is_el, f"{{{XLSX_NS['s']}}}t")
    # Preserve leading/trailing spaces if any
    if text and (text[0].isspace() or text[-1].isspace()):
        t_el.attrib["{http://www.w3.org/XML/1998/namespace}space"] = "preserve"
    t_el.text = "" if text is None else str(text)

def set_cell_number(sheet_root, row_num: int, col_letters: str, num):
    row = _ensure_row(sheet_root, row_num)
    cell = _ensure_cell(sheet_root, row, col_letters, row_num)
    for child in list(cell):
        cell.remove(child)
    if "t" in cell.attrib:
        del cell.attrib["t"]
    v = ET.SubElement(cell, f"{{{XLSX_NS['s']}}}v")
