        mm = re.search(r"\bMRN\s*[:\-]\s*(\d+)\b", blob, re.I)
        if mm:
            mrn = mm.group(1)

        # Extract month-lab rows by scanning for month tokens and nearby lab values
        # Common analytes (tunable):
        lab_keys = {
            "kt/v": ["kt/v", "ktv", "kt v"],
            "hgb": ["hgb", "hgb.", "hemoglobin", "hb"],
            "calcium": ["calcium", "ca"],
            "phosphorus": ["phosphorus", "phos", "phosph", "p"],
            "albumin": ["albumin", "alb"],
            "tsat": ["tsat"],
            "ferritin": ["ferritin"],
        }

        month_entries = []

        # Pattern: Month: X ... Key: value ...
        month_pat = re.compile(r"\b(month|date)\s*[:\-]\s*([A-Za-z]{3,9}\s+\d{4}|\d{4}-\d{2}|\d{2}/\d{4}|[A-Za-z]{3,9})\b", re.I)
        matches = list(month_pat.finditer(blob))
        if not matches:
            # fallback: if document uses headings like "January" alone on a line
            for ln in sec:
                tok = parse_month_token(ln)
                if tok:
                    matches.append(re.match(r".*", ln))  # placeholder; handle below via per-line parsing

        if matches and isinstance(matches[0], re.Match):
            # Iterate chunks between month markers
            for i, mth in enumerate(matches):
                start = mth.start()
                end = matches[i + 1].start() if i + 1 < len(matches) else len(blob)
                chunk = blob[start:end]

                mmm = month_pat.search(chunk)
                if mmm:
                    token = mmm.group(2)
                    ym = parse_month_token(token)
                else:
                    # placeholder: can't get month from chunk reliably
                    ym = None

                year = None
                month = None
                if ym:
                    year, month = ym
                # Try month name w/out year: set year later
                if month is None:
                    # find month name in chunk
                    mn = re.search(r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\b", chunk, re.I)
                    if mn:
                        month = MONTHS[mn.group(1).lower()]
                # Extract labs from chunk
                labs = {}
                for canon, aliases in lab_keys.items():
                    for al in aliases:
                        mx = re.search(rf"\b{re.escape(al)}\b\s*[:\-]?\s*([0-9]+(?:\.[0-9]+)?)", chunk, re.I)
                        if mx:
                            labs[canon] = float(mx.group(1))
                            break
                    # if found, stop checking aliases
                if labs and month is not None:
                    month_entries.append({"year": year, "month": month, "labs": labs})

        # If years are missing, infer as current year and adjust (or leave None)
        now_year = _dt.date.today().year
        for e in month_entries:
            if e["year"] is None:
                e["year"] = now_year

        patients[name] = {"mrn": mrn or "", "months": month_entries}

    return patients

