def assign_provider(name: str) -> str:
    """
    From the prompt:
      Dr. Joe: Cash Stonewater, Fred Fintmore
      Dr. Johnson: Betty Brite, Tina Lee Bell
      Dr. Lee: Eric Bird, Homer Sandson
      Dr. Michael: Jessica Rashmore
    """
    name_n = normalize_name(name).lower()
    mapping = {
        "cash stonewater": "Dr. Joe",
        "fred fintmore": "Dr. Joe",
        "betty brite": "Dr. Johnson",
        "tina lee bell": "Dr. Johnson",
        "eric bird": "Dr. Lee",
        "homer sandson": "Dr. Lee",
        "jessica rashmore": "Dr. Michael",
    }
    return mapping.get(name_n, "")

def month_key(y: int, m: int) -> str:
    return f"{y:04d}-{m:02d}"

def apply_monthly_changes(provider: str, month_labs: dict, prior_meds: dict) -> (dict, str):
    """
    Rules (from prompt):
      - Start with no current medication orders unless directed.
      - Repeat lab work in one month if KT/V < 1.2.
      - If calcium between 7.9-8.4 => TUMS 2 tabs PO 3x/week.
      - If HGB < 10.0 => start Aranesp 10 mcg IVP each treatment.
      - If currently on Aranesp 10 mcg each treatment and needs dose decrease per protocol => decrease to 10 mcg IVP 2x/week.
