def find_header_map(sheet_root, header_row=1, max_cols=80):
    """
    Returns dict canonical_key -> column_letters
    """
    headers = {}
    for cnum in range(1, max_cols + 1):
        col = num_to_col(cnum)
        txt = get_cell_text(sheet_root, f"{col}{header_row}")
        if not txt:
            continue
        low = txt.strip().lower()
        for canon, aliases in HEADER_ALIASES.items():
            if canon in headers:
                continue
            if any(a == low for a in aliases):
                headers[canon] = col
    return headers

