    # Preserve leading/trailing spaces if any
    if text and (text[0].isspace() or text[-1].isspace()):
        t_el.attrib["{http://www.w3.org/XML/1998/namespace}space"] = "preserve"
    t_el.text = "" if text is None else str(text)

def set_cell_number(sheet_root, row_num: int, col_letters: str, num):
    row = _ensure_row(sheet_root, row_num)
    cell = _ensure_cell(sheet_root, row, col_letters, row_num)
    for child in list(cell):
        cell.remove(child)
    if "t" in cell.attrib:
        del cell.attrib["t"]
    v = ET.SubElement(cell, f"{{{XLSX_NS['s']}}}v")
    v.text = str(num)

def get_cell_text(sheet_root, a1: str) -> str:
    col, rnum = split_cell_ref(a1)
    row = _find_row(sheet_root, rnum)
    if row is None:
        return ""
    cell = _find_cell(row, a1)
    if cell is None:
        return ""
    t = cell.attrib.get("t")
    if t == "inlineStr":
        t_el = cell.find(".//s:is/s:t", XLSX_NS)
        return (t_el.text or "") if t_el is not None else ""
    # for other types, try v
    v_el = cell.find("s:v", XLSX_NS)
    return (v_el.text or "") if v_el is not None else ""

# -----------------------------
# Parsing lab report text
# -----------------------------
MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

def normalize_name(s: str) -> str:
    return re.sub(r"\s+", " ", (s or "").strip())

def parse_month_token(s: str):
    # Accept "Jan", "January", "2025-01", "01/2025"
    s = (s or "").strip()
    m = re.match(r"^(\d{4})-(\d{2})$", s)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.match(r"^(\d{2})/(\d{4})$", s)
    if m:
        return int(m.group(2)), int(m.group(1))
    low = s.lower()
    if low in MONTHS:
        # Year not known; caller can fill
        return None, MONTHS[low]
    m = re.match(r"^(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\s+(\d{4})$", low)
    if m:
        return int(m.group(2)), MONTHS[m.group(1)]
    return None

def parse_patient_lab_reports(text: str):
    """
    Heuristic parser. Expected to find per-patient blocks with:
      Patient: <name>
      MRN: <digits>
      Month: <...>  KT/V: <...>  HGB: <...>  Calcium: <...>  Phosphorus: <...> Albumin: <...>
    Returns:
      {name: {"mrn": "...", "months": [{"year":..., "month":..., "labs":{...}}, ...]}}
    """
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    # Split into patient sections by "Patient" lines or all-caps names if present
    sections = []
    cur = []
    for ln in lines:
        if re.match(r"^(patient|name)\s*[:\-]", ln, re.I) and cur:
            sections.append(cur)
            cur = [ln]
        else:
            cur.append(ln)
    if cur:
        sections.append(cur)

    patients = {}
    for sec in sections:
        blob = "\n".join(sec)

        name = None
        m = re.search(r"^(?:patient|name)\s*[:\-]\s*(.+)$", sec[0], re.I)
        if m:
            name = normalize_name(m.group(1))
        else:
            # try within blob
            m2 = re.search(r"(?:patient|name)\s*[:\-]\s*(.+)", blob, re.I)
            if m2:
                name = normalize_name(m2.group(1).splitlines()[0])
        if not name:
            continue

        mrn = None
        mm = re.search(r"\bMRN\s*[:\-]\s*(\d+)\b", blob, re.I)
        if mm:
            mrn = mm.group(1)

        # Extract month-lab rows by scanning for month tokens and nearby lab values
        # Common analytes (tunable):
        lab_keys = {
            "kt/v": ["kt/v", "ktv", "kt v"],
            "hgb": ["hgb", "hgb.", "hemoglobin", "hb"],
            "calcium": ["calcium", "ca"],
            "phosphorus": ["phosphorus", "phos", "phosph", "p"],
            "albumin": ["albumin", "alb"],
            "tsat": ["tsat"],
            "ferritin": ["ferritin"],
        }

        month_entries = []

        # Pattern: Month: X ... Key: value ...
        month_pat = re.compile(r"\b(month|date)\s*[:\-]\s*([A-Za-z]{3,9}\s+\d{4}|\d{4}-\d{2}|\d{2}/\d{4}|[A-Za-z]{3,9})\b", re.I)
        matches = list(month_pat.finditer(blob))
        if not matches:
            # fallback: if document uses headings like "January" alone on a line
            for ln in sec:
                tok = parse_month_token(ln)
                if tok:
                    matches.append(re.match(r".*", ln))  # placeholder; handle below via per-line parsing

        if matches and isinstance(matches[0], re.Match):
            # Iterate chunks between month markers
            for i, mth in enumerate(matches):
                start = mth.start()
                end = matches[i + 1].start() if i + 1 < len(matches) else len(blob)
                chunk = blob[start:end]

                mmm = month_pat.search(chunk)
                if mmm:
                    token = mmm.group(2)
                    ym = parse_month_token(token)
                else:
                    # placeholder: can't get month from chunk reliably
                    ym = None

                year = None
                month = None
                if ym:
                    year, month = ym
                # Try month name w/out year: set year later
                if month is None:
                    # find month name in chunk
                    mn = re.search(r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\b", chunk, re.I)
                    if mn:
                        month = MONTHS[mn.group(1).lower()]
                # Extract labs from chunk
                labs = {}
                for canon, aliases in lab_keys.items():
                    for al in aliases:
                        mx = re.search(rf"\b{re.escape(al)}\b\s*[:\-]?\s*([0-9]+(?:\.[0-9]+)?)", chunk, re.I)
                        if mx:
                            labs[canon] = float(mx.group(1))
                            break
                    # if found, stop checking aliases
                if labs and month is not None:
                    month_entries.append({"year": year, "month": month, "labs": labs})

        # If years are missing, infer as current year and adjust (or leave None)
        now_year = _dt.date.today().year
        for e in month_entries:
            if e["year"] is None:
                e["year"] = now_year

        patients[name] = {"mrn": mrn or "", "months": month_entries}

    return patients

# -----------------------------
# Standing order rules engine
# -----------------------------
def assign_provider(name: str) -> str:
    """
    From the prompt:
      Dr. Joe: Cash Stonewater, Fred Fintmore
      Dr. Johnson: Betty Brite, Tina Lee Bell
      Dr. Lee: Eric Bird, Homer Sandson
      Dr. Michael: Jessica Rashmore
    """
    name_n = normalize_name(name).lower()
    mapping = {
        "cash stonewater": "Dr. Joe",
        "fred fintmore": "Dr. Joe",
        "betty brite": "Dr. Johnson",
        "tina lee bell": "Dr. Johnson",
        "eric bird": "Dr. Lee",
        "homer sandson": "Dr. Lee",
        "jessica rashmore": "Dr. Michael",
    }
    return mapping.get(name_n, "")

def month_key(y: int, m: int) -> str:
    return f"{y:04d}-{m:02d}"

def apply_monthly_changes(provider: str, month_labs: dict, prior_meds: dict) -> (dict, str):
    """
    Rules (from prompt):
      - Start with no current medication orders unless directed.
      - Repeat lab work in one month if KT/V < 1.2.
      - If calcium between 7.9-8.4 => TUMS 2 tabs PO 3x/week.
      - If HGB < 10.0 => start Aranesp 10 mcg IVP each treatment.
      - If currently on Aranesp 10 mcg each treatment and needs dose decrease per protocol => decrease to 10 mcg IVP 2x/week.
        (Dose decrease table not provided in prompt text; we implement a conservative placeholder rule:
           if HGB >= 11.0 while on Aranesp 10 mcg each treatment => decrease to 2x/week.)
      - Phosphate binders:
        * Dr. Joe/Dr. Johnson: Renvela 800 mg PO with meals if phos 5.6-7.4; if 4.0-5.5 continue most recent Renvela unchanged.
        * Dr. Lee/Dr. Michael: Phoslo 667 mg 2 tabs PO with each meal if phos 5.5-7.4; if 4.0-5.5 continue most recent Phoslo unchanged.
    """
    meds = dict(prior_meds or {})
    notes = []

    ktv = month_labs.get("kt/v")
    hgb = month_labs.get("hgb")
    ca = month_labs.get("calcium")
    phos = month_labs.get("phosphorus")

    if ktv is not None and ktv < 1.2:
        notes.append("Order: Repeat adequacy labs in 1 month (KT/V < 1.2).")

    # Calcium/TUMS
    if ca is not None and 7.9 <= ca <= 8.4:
        if meds.get("tums") != "TUMS 2 tabs PO 3x/week":
            meds["tums"] = "TUMS 2 tabs PO 3x/week"
            notes.append("Start TUMS 2 tabs PO 3x/week (Ca 7.9-8.4).")
    # If outside range, do not automatically stop (prompt doesn't instruct discontinuation).

    # Anemia/Aranesp
    if hgb is not None:
        if hgb < 10.0:
            if meds.get("aranesp") != "Aranesp 10 mcg IVP each treatment":
                meds["aranesp"] = "Aranesp 10 mcg IVP each treatment"
                notes.append("Start Aranesp 10 mcg IVP each treatment (HGB < 10.0).")
        else:
            # Placeholder dose decrease logic due to missing table text
            if meds.get("aranesp") == "Aranesp 10 mcg IVP each treatment" and hgb >= 11.0:
                meds["aranesp"] = "Aranesp 10 mcg IVP 2x/week"
                notes.append("Decrease Aranesp to 10 mcg IVP 2x/week (HGB >= 11.0; per protocol dose decrease placeholder).")

    # Phosphorus binders by provider
    if phos is not None:
        if provider in ("Dr. Joe", "Dr. Johnson"):
            # Renvela logic
            if 5.6 <= phos <= 7.4:
                if "renvela" not in meds:
                    meds["renvela"] = "Renvela 800 mg PO with meals"
                    notes.append("Start Renvela 800 mg PO with meals (Phos 5.6-7.4).")
                else:
                    # titration not performed automatically without 2-week cadence and pill count history
                    notes.append("Consider Renvela titration by 800 mg/meal q2 weeks if Phos remains above goal (max 4 tabs/meal).")
            elif 4.0 <= phos <= 5.5:
                if "renvela" in meds:
                    notes.append("Continue current Renvela dose (Phos 4.0-5.5).")
        if provider in ("Dr. Lee", "Dr. Michael"):
            # Phoslo logic
            if 5.5 <= phos <= 7.4:
                if "phoslo" not in meds:
                    meds["phoslo"] = "Phoslo 667 mg, 2 tabs PO with each meal"
                    notes.append("Start Phoslo 667 mg, 2 tabs PO with each meal (Phos 5.5-7.4).")
                else:
                    notes.append("Consider Phoslo titration by 667 mg/meal q2 weeks if Phos remains above goal.")
            elif 4.0 <= phos <= 5.5:
                if "phoslo" in meds:
                    notes.append("Continue current Phoslo dose (Phos 4.0-5.5).")

    note_text = " ".join(notes).strip()
    return meds, note_text

# -----------------------------
# Tracker fill logic
# -----------------------------
HEADER_ALIASES = {
    "patient name": ["patient", "patient name", "name"],
    "mrn": ["mrn", "medical record", "medical record number"],
    "month": ["month", "date", "report month"],
    "kt/v": ["kt/v", "ktv"],
    "hgb": ["hgb", "hemoglobin", "hb"],
    "calcium": ["calcium", "ca"],
    "phosphorus": ["phosphorus", "phos"],
    "albumin": ["albumin", "alb"],
    "notes": ["notes", "med changes", "medication changes", "treatment changes", "actions"],
    "provider": ["provider", "md", "doctor"],
}

def find_header_map(sheet_root, header_row=1, max_cols=80):
    """
    Returns dict canonical_key -> column_letters
    """
    headers = {}
    for cnum in range(1, max_cols + 1):
        col = num_to_col(cnum)
        txt = get_cell_text(sheet_root, f"{col}{header_row}")
        if not txt:
            continue
        low = txt.strip().lower()
        for canon, aliases in HEADER_ALIASES.items():
            if canon in headers:
                continue
            if any(a == low for a in aliases):
                headers[canon] = col
    return headers

def ensure_required_headers(headers: dict):
    req = ["patient name", "mrn", "month", "notes"]
    missing = [r for r in req if r not in headers]
    if missing:
        raise ValueError("Missing required columns in tracker header row: " + ", ".join(missing))

def find_or_append_row(sheet_root, headers: dict, patient: str, mrn: str, month_str: str, header_row=1, start_row=2, scan_limit=5000):
    """
    Find row where (patient name == patient) and (month == month_str).
    If none, append at first empty row.
    """
    pname_col = headers["patient name"]
    month_col = headers["month"]
    mrn_col = headers.get("mrn")

    first_empty = None
    for r in range(start_row, scan_limit + 1):
        pname = get_cell_text(sheet_root, f"{pname_col}{r}").strip()
        mtxt = get_cell_text(sheet_root, f"{month_col}{r}").strip()
        if not pname and not mtxt:
            first_empty = r
            break
        if normalize_name(pname).lower() == normalize_name(patient).lower() and mtxt == month_str:
            return r

    if first_empty is None:
        first_empty = scan_limit + 1

    # Populate key identity columns on new row
    set_cell_inline_str(sheet_root, first_empty, pname_col, patient)
    if mrn_col:
        set_cell_inline_str(sheet_root, first_empty, mrn_col, mrn or "")
    set_cell_inline_str(sheet_root, first_empty, month_col, month_str)
    if "provider" in headers:
        set_cell_inline_str(sheet_root, first_empty, headers["provider"], assign_provider(patient))
    return first_empty

def fill_tracker(tracker_xlsx: str, out_xlsx: str, patient_data: dict):
    with zipfile.ZipFile(tracker_xlsx, "r") as z:
        sheet_path = _get_first_sheet_path(z)
        sheet_xml = z.read(sheet_path)
        sheet_root = ET.fromstring(sheet_xml)

        headers = find_header_map(sheet_root, header_row=1)
        ensure_required_headers(headers)

        # Keep per-patient medication state across months
        for patient_name, pdata in patient_data.items():
            provider = assign_provider(patient_name)
            meds_state = {}  # starts empty per prompt
            # sort months
            months = sorted(pdata.get("months", []), key=lambda e: (e.get("year", 0), e.get("month", 0)))
            for e in months:
                y, m = e["year"], e["month"]
                labs = e["labs"]
                mstr = month_key(y, m)

                meds_state, note = apply_monthly_changes(provider, labs, meds_state)

                row = find_or_append_row(
                    sheet_root, headers,
                    patient=patient_name,
                    mrn=pdata.get("mrn",""),
                    month_str=mstr
                )

                # Fill lab values if columns exist
                def _maybe_num(canon_key, val):
                    if canon_key in headers and val is not None:
                        set_cell_number(sheet_root, row, headers[canon_key], val)

                _maybe_num("kt/v", labs.get("kt/v"))
                _maybe_num("hgb", labs.get("hgb"))
                _maybe_num("calcium", labs.get("calcium"))
                _maybe_num("phosphorus", labs.get("phosphorus"))
                _maybe_num("albumin", labs.get("albumin"))

                # Notes / med changes
                if "notes" in headers:
                    # Include active meds summary + monthly note
                    med_summary = []
                    for k in sorted(meds_state):
                        med_summary.append(meds_state[k])
                    med_txt = "; ".join(med_summary).strip()
                    combined = (med_txt + (" | " if (med_txt and note) else "") + note).strip()
                    set_cell_inline_str(sheet_root, row, headers["notes"], combined)

        # Write out new XLSX with updated sheet XML
        new_sheet_xml = ET.tostring(sheet_root, encoding="utf-8", xml_declaration=True)

        # Copy all files, replacing worksheet
        with zipfile.ZipFile(out_xlsx, "w", compression=zipfile.ZIP_DEFLATED) as outz:
            for item in z.infolist():
                if item.filename == sheet_path:
                    outz.writestr(item, new_sheet_xml)
                else:
                    outz.writestr(item, z.read(item.filename))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--lab_docx", required=True, help="Patient Lab Reports.docx")
    ap.add_argument("--tracker_xlsx", required=True, help="Monthly Tracker- Patient Lab Results.xlsx")
