# REASONING: Detect task type, then parse any structured log data from input_0 (work orders/complaints) to compute KPI metrics; generate a formal 90-day PIP document text with specific objectives, training, supports, and signatures.
import re, json, datetime, collections   # MANDATORY first code line

# --- STEP 0: DETECT TASK TYPE (MANDATORY) ---
has_mcq = any(f"{c})" in task_0 for c in "ABCD")  # Multiple choice?
