def parse_date(s):
    s = (s or "").strip()
    if not s:
        return None
    if len(s) >= 10 and s[4] == '-':
        try:
            return datetime.datetime.strptime(s[:10], "%Y-%m-%d")
        except Exception:
            pass
    for fmt in ["%b %d, %Y", "%m/%d/%Y", "%d/%m/%Y", "%B %d, %Y", "%m/%d/%y", "%m-%d-%Y", "%Y/%m/%d"]:
        try:
            return datetime.datetime.strptime(s, fmt)
        except Exception:
            continue
    # Try datetime stamps
    for fmt in ["%m/%d/%Y %H:%M", "%m/%d/%Y %I:%M %p", "%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"]:
        try:
            return datetime.datetime.strptime(s, fmt)
        except Exception:
            continue
    return None

def business_hours_diff(start_dt, end_dt):
    # Approximate business hours between datetimes: Mon-Fri, 9:00-17:00.
    if not start_dt or not end_dt:
        return None
    if end_dt < start_dt:
        return 0.0
    total = 0.0
    cur = start_dt
    one_day = datetime.timedelta(days=1)
    while cur.date() <= end_dt.date():
        day_start = datetime.datetime(cur.year, cur.month, cur.day, 9, 0, 0)
        day_end = datetime.datetime(cur.year, cur.month, cur.day, 17, 0, 0)
        if cur.weekday() < 5:  # Mon-Fri
            s = max(start_dt, day_start)
            e = min(end_dt, day_end)
            if e > s:
                total += (e - s).total_seconds() / 3600.0
        cur = datetime.datetime(cur.year, cur.month, cur.day) + one_day
    return total

def infer_delim(sample):
    if "||" in sample:
        return "||"
    if "\t" in sample and sample.count("\t") > sample.count("|"):
        return "\t"
    if "|" in sample:
        return "|"
    # fallback: CSV-like
    return ","

def parse_structured_records(text):
    sample = text[:5000]
    delim = infer_delim(sample)
    lines = [l for l in text.splitlines() if delim in l]
    records = []
    for line in lines:
        rec = {}
        for part in line.split(delim):
            if ":" in part:
                k, v = part.split(":", 1)
                rec[k.strip().lower()] = v.strip()
        if rec:
            records.append(rec)
    return delim, records

def choose_workorder_and_complaint_records(records):
    # Heuristic: separate by presence of work-order-like keys vs complaint-like keys
    wo_keys = {"work order", "workorder", "wo", "ticket", "request", "unit", "apartment", "created", "submitted", "opened", "acknowledged", "ack", "completed", "closed", "category", "trade", "redo", "rework"}
    comp_keys = {"complaint", "resident", "noise", "rude", "professional", "attitude", "response", "delay", "follow-up", "unsanitary", "missed", "no show"}
    work_orders = []
    complaints = []
    for r in records:
        keys = set(r.keys())
        wo_score = sum(1 for k in keys for w in wo_keys if w in k)
        comp_score = sum(1 for k in keys for w in comp_keys if w in k)
        # also look at explicit log type fields
        logtype = (r.get("type") or r.get("log") or r.get("record") or "").lower()
        if "work" in logtype and "order" in logtype:
            work_orders.append(r); continue
        if "complaint" in logtype or "resident complaint" in logtype:
            complaints.append(r); continue
        if wo_score >= comp_score and wo_score > 0:
            work_orders.append(r)
        elif comp_score > 0:
            complaints.append(r)
        else:
            # unknown; keep for later
            pass
    return work_orders, complaints

def pick_field(rec, candidates):
    for c in candidates:
        if c in rec:
            return rec[c]
    # also allow partial matches
    for k in rec.keys():
        lk = k.lower()
        for c in candidates:
            if c in lk:
                return rec[k]
    return None

def compute_workorder_kpis(work_orders, employee_name="John Miller"):
    # Identify fields
    parsed = []
