            "category": category,
            "created": created,
            "ack": ack,
            "completed": completed,
            "redo": redo
        })

    total = len(parsed)
    # Metrics
    ack_hours = []
    ack_within_4bh = 0
    ack_missing = 0
    completion_hours = []
    completed_within_72h = 0
    completed_missing = 0
    redo_count = 0
    redo_known = 0

    for p in parsed:
        if p["created"] and p["ack"]:
            bh = business_hours_diff(p["created"], p["ack"])
            if bh is not None:
                ack_hours.append(bh)
                if bh <= 4.0:
                    ack_within_4bh += 1
        else:
            ack_missing += 1

        if p["created"] and p["completed"]:
            dh = (p["completed"] - p["created"]).total_seconds() / 3600.0
            completion_hours.append(dh)
            if dh <= 72.0:
                completed_within_72h += 1
        else:
            completed_missing += 1

        if p["redo"] is not None:
            redo_known += 1
            if p["redo"]:
                redo_count += 1

    def pct(n, d):
        return None if d == 0 else (100.0 * n / d)

    kpis = {
        "total_work_orders": total,
        "ack_measured_n": len(ack_hours),
        "ack_missing_n": ack_missing,
        "ack_within_4bh_n": ack_within_4bh,
        "ack_within_4bh_pct": pct(ack_within_4bh, len(ack_hours)),
        "ack_avg_bh": (sum(ack_hours) / len(ack_hours)) if ack_hours else None,
        "ack_median_bh": (sorted(ack_hours)[len(ack_hours)//2] if ack_hours else None),

        "completion_measured_n": len(completion_hours),
        "completion_missing_n": completed_missing,
        "completed_within_72h_n": completed_within_72h,
        "completed_within_72h_pct": pct(completed_within_72h, len(completion_hours)),
        "completion_avg_h": (sum(completion_hours) / len(completion_hours)) if completion_hours else None,
        "completion_median_h": (sorted(completion_hours)[len(completion_hours)//2] if completion_hours else None,

        ),
        "redo_known_n": redo_known,
        "redo_n": redo_count,
        "redo_rate_pct": pct(redo_count, redo_known)  # may be None
    }
    return kpis, parsed

def summarize_complaints(complaints, employee_name="John Miller"):
    # Build theme counts from category/type/issue + free text fields
    theme_counter = collections.Counter()
    by_month = collections.Counter()
    total = 0
    examples = collections.defaultdict(list)

    for r in complaints:
        assignee = (pick_field(r, ["employee", "staff", "superintendent", "involved", "assigned to", "assignee"]) or "").strip()
        if assignee and assignee.lower() != employee_name.lower():
            continue

        total += 1
        dt_s = pick_field(r, ["date", "logged", "submitted", "created", "received"])
        dt = parse_date(dt_s) if dt_s else None
        if dt:
            by_month[dt.strftime("%Y-%m")] += 1

        cat = (pick_field(r, ["category", "type", "theme", "topic"]) or "").strip()
        text = (pick_field(r, ["details", "notes", "complaint", "description", "summary"]) or "").strip()

        blob = " ".join([cat, text]).lower()
        # Simple theme tagging
        theme_map = {
            "timeliness / delays": ["delay", "late", "slow", "no response", "unanswered", "not acknowledged", "waiting", "72", "hours", "overdue", "missed"],
            "communication / professionalism": ["rude", "unprofessional", "attitude", "tone", "dismissive", "argue", "yell", "customer service", "communication"],
            "work quality / repeat visits": ["redo", "rework", "not fixed", "still leaking", "same issue", "temporary", "poor quality", "unfinished", "incorrect"],
            "access / scheduling / no-show": ["no show", "didn't show", "missed appointment", "schedule", "reschedule", "access", "entry notice"],
            "safety / code concerns": ["unsafe", "electrical", "sparking", "fire", "smoke", "shock", "panel", "breaker", "nfpa", "70e"]
        }
        tagged = False
        for theme, kws in theme_map.items():
            if any(kw in blob for kw in kws):
                theme_counter[theme] += 1
                if len(examples[theme]) < 2 and text:
                    examples[theme].append(text[:220])
                tagged = True
        if not tagged:
            if cat:
                theme_counter[cat.lower()] += 1
                if len(examples[cat.lower()]) < 2 and text:
                    examples[cat.lower()].append(text[:220])
            elif text:
                theme_counter["other / unspecified"] += 1
                if len(examples["other / unspecified"]) < 2:
                    examples["other / unspecified"].append(text[:220])

    top_themes = theme_counter.most_common(5)
    return {
        "total_complaints": total,
        "by_month": dict(by_month),
        "top_themes": top_themes,
        "examples": {k: v for k, v in examples.items()}
    }

def fmt_pct(x, nd=1):
    if x is None:
        return "N/A"
    return f"{x:.{nd}f}%"

def fmt_num(x, nd=1):
    if x is None:
        return "N/A"
    return f"{x:.{nd}f}"

