# REASONING: Enumerate quadratic intersections on each linear segment, deduplicate exact y-values, sum them as a linear combination of squarefree radicals, and use the problem guarantee (single radical) to collapse to (a+b*sqrt(c))/d and output a+b+c+d.
import re, json, datetime, collections  # MANDATORY first code line

from fractions import Fraction
import math

has_mcq = any(f"{c})" in task_0 for c in "ABCD")
is_code_task = any(k in task_0.lower() for k in ["codebase","exact function","code snippet"])
is_code_gen = any(k in task_0.lower() for k in ["write a complete","solve this programming problem","implement the given function"])
is_creative = any(k in task_0.lower() for k in ["write a proposal","draft a report","generate a report","write a summary","create a document","write a letter","write an essay"])

def is_square(n: int) -> bool:
    if n < 0:
        return False
    r = int(math.isqrt(n))
    return r * r == n

def squarefree_decompose(n: int):
    """Return (k, sf) with n = k^2 * sf and sf squarefree."""
    if n == 0:
        return (0, 0)
    nn = n
    k = 1
    sf = 1
    p = 2
    while p * p <= nn:
        if nn % p == 0:
            e = 0
            while nn % p == 0:
                nn //= p
                e += 1
            k *= p ** (e // 2)
            if e % 2 == 1:
                sf *= p
        p += 1 if p == 2 else 2
    if nn > 1:
        sf *= nn
    return (k, sf)

def make_roots_quadratic(A, B, C):
    """Solve A t^2 + B t + C = 0; return roots as triples (a,b,sf) meaning a + b*sqrt(sf)."""
    D = B * B - 4 * A * C
    if D < 0:
        return []
    if is_square(D):
        r = int(math.isqrt(D))
        denom = 2 * A
        return [(Fraction(-B + r, denom), Fraction(0), 0),
                (Fraction(-B - r, denom), Fraction(0), 0)]
    k, sf = squarefree_decompose(D)
    denom = 2 * A
    base = Fraction(-B, denom)
    coef = Fraction(k, denom)
    return [(base, coef, sf), (base, -coef, sf)]

def approx_val(a, b, sf):
    if sf == 0 or b == 0:
        return float(a)
    return float(a) + float(b) * math.sqrt(sf)

def in_interval(v, lo, hi, right_open=False):
    if right_open:
        return (v >= lo - 1e-12) and (v < hi - 1e-12)
    return (v >= lo - 1e-12) and (v <= hi + 1e-12)

# Collect unique y-values exactly as tuples (a,b,sf) in reduced form
def norm_y(a, b, sf):
    a = Fraction(a)
    b = Fraction(b)
    sf = int(sf)
    if b == 0 or sf == 0:
        return (a, Fraction(0), 0)
    # ensure sf squarefree (it already should be) and normalize sign in b
    if b < 0:
        return (a, b, sf)
    return (a, b, sf)

ys_set = set()

for n in range(0, 9):
    # Segment 1: x in [4n-1,4n+1), y=t in [-1,1)
    # equation: x = t+4n = 34 t^2 => 34 t^2 - t - 4n = 0
    for a, b, sf in make_roots_quadratic(34, -1, -4 * n):
        tv = approx_val(a, b, sf)
        if not in_interval(tv, -1, 1, right_open=True):
            continue
        xv = approx_val(a + 4 * n, b, sf)
        if not in_interval(xv, 0, 34, right_open=False):
            continue
        if not in_interval(xv, 4 * n - 1, 4 * n + 1, right_open=True):
            continue
        ys_set.add(norm_y(a, b, sf))

    # Segment 2: x in [4n+1,4n+3), y=u in (-1,1]
    # equation: x = 4n+2 - u = 34 u^2 => 34u^2 + u - (4n+2) = 0
    for a, b, sf in make_roots_quadratic(34, 1, -(4 * n + 2)):
        uv = approx_val(a, b, sf)
        if not (uv > -1 + 1e-12 and uv <= 1 + 1e-12):
            continue
        # x = 4n+2 - u
        xv = approx_val(Fraction(4 * n + 2) - a, -b, sf)
        if not in_interval(xv, 0, 34, right_open=False):
            continue
        if not in_interval(xv, 4 * n + 1, 4 * n + 3, right_open=True):
            continue
        ys_set.add(norm_y(a, b, sf))

# Sum as rational + sum_sf coef_sf * sqrt(sf)
rat = Fraction(0)
coef = collections.Counter()  # sf -> Fraction
for a, b, sf in ys_set:
    rat += a
    if sf != 0 and b != 0:
        coef[sf] += b

# Remove zero coefficients
coef = {sf: c for sf, c in coef.items() if c != 0}

# Problem guarantee: exactly one radical term
if len(coef) == 0:
    # purely rational
    a_num = rat.numerator
    d_den = rat.denominator
    a_int = abs(a_num)
    b_int = 0
    c_int = 1
    d_int = d_den
else:
    if len(coef) != 1:
        # As a safety: try to see if tiny numeric cancellation happened; check near-zero by float
        # (but here exact Fractions used, so this should not happen)
        raise ValueError(f"Unexpected multiple radicals in exact sum: {coef}")
    (c_int, b_frac) = next(iter(coef.items()))
    a_frac = rat

    # Combine into (A + B*sqrt(c))/D
    D = (a_frac.denominator * b_frac.denominator) // math.gcd(a_frac.denominator, b_frac.denominator)
    A = a_frac.numerator * (D // a_frac.denominator)
    B = b_frac.numerator * (D // b_frac.denominator)

    g = math.gcd(abs(A), math.gcd(abs(B), D))
    A //= g
    B //= g
    D //= g

    a_int = abs(A)
    b_int = abs(B)
    d_int = D

answer = a_int + b_int + c_int + d_int
