from typing import List

MOD = 10**9 + 7

class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        # Invariant: the multiset of bit counts across all numbers is preserved.
        # Operation lets us redistribute bits across elements, so optimal is:
        # build k numbers greedily, each taking as many available bits as possible.
        bit_cnt = [0] * 31
        for x in nums:
            b = 0
            while x:
                if x & 1:
                    bit_cnt[b] += 1
                x >>= 1
                b += 1

        ans = 0
        for _ in range(k):
            val = 0
            for b in range(31):
                if bit_cnt[b] > 0:
                    bit_cnt[b] -= 1
                    val |= (1 << b)
            ans = (ans + (val * val) % MOD) % MOD

        return ans
