class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        n = len(s)

        # Precompute all binary strings representing powers of 5 that could fit in length n
        powers = set()
        val = 1  # 5^0
        while True:
            b = bin(val)[2:]  # no leading '0b'
            if len(b) > n:
                break
            powers.add(b)
            val *= 5

        INF = 10**9
        dp = [INF] * (n + 1)
        dp[0] = 0

        for i in range(n):
            if dp[i] == INF:
                continue
            if s[i] == '0':  # any substring starting here would have a leading zero
                continue
            for j in range(i + 1, n + 1):
                if s[i:j] in powers:
                    dp[j] = min(dp[j], dp[i] + 1)

        return -1 if dp[n] == INF else dp[n]
