class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        # If any value is 1 and n>1, it has gcd=1 with everything, so disconnected.
        if any(x == 1 for x in nums):
            return False

        maxA = max(nums)

        # Smallest prime factor sieve up to maxA
        spf = list(range(maxA + 1))
        for i in range(2, int(maxA ** 0.5) + 1):
            if spf[i] == i:  # prime
                step = i
                start = i * i
                for j in range(start, maxA + 1, step):
                    if spf[j] == j:
                        spf[j] = i

        def factorize_distinct(x: int):
            """Return distinct prime factors of x using spf."""
            res = []
            while x > 1:
                p = spf[x]
                res.append(p)
                while x % p == 0:
                    x //= p
            return res

        # DSU over indices 0..n-1; union indices that share a prime factor.
        parent = list(range(n))
        size = [1] * n

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        # Map prime -> first index that had this prime; union with later ones.
        first_idx_for_prime = {}

        for i, val in enumerate(nums):
            for p in factorize_distinct(val):
                if p in first_idx_for_prime:
                    union(i, first_idx_for_prime[p])
                else:
                    first_idx_for_prime[p] = i

        root0 = find(0)
        for i in range(1, n):
            if find(i) != root0:
                return False
        return True
