class TrieNode:
    __slots__ = ("children", "end")
    def __init__(self):
        self.children = {}
        self.end = False

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        # Build trie
        root = TrieNode()
        for w in dictionary:
            node = root
            for ch in w:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.end = True

        n = len(s)
        dp = [0] * (n + 1)
        dp[n] = 0

        for i in range(n - 1, -1, -1):
            best = 1 + dp[i + 1]  # skip s[i] as extra

            node = root
            j = i
            while j < n and s[j] in node.children:
                node = node.children[s[j]]
                j += 1
                if node.end:
                    best = min(best, dp[j])

            dp[i] = best

        return dp[0]

