class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        # Find all start positions where pattern p occurs in s (KMP)
        def kmp_positions(text: str, pat: str) -> List[int]:
            n, m = len(text), len(pat)
            if m == 0:
                return list(range(n + 1))
            # build lps (longest proper prefix which is also suffix)
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            res = []
            j = 0
            for i in range(n):
                while j > 0 and text[i] != pat[j]:
                    j = lps[j - 1]
                if text[i] == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = lps[j - 1]
            return res

        A = kmp_positions(s, a)
        B = kmp_positions(s, b)

        # Two-pointer sweep: for each i in A, check if any j in B within [i-k, i+k]
        ans = []
        p = 0  # pointer into B
        for i in A:
            left = i - k
            right = i + k

            # advance p so that B[p] is the first >= left
            while p < len(B) and B[p] < left:
                p += 1

            # if current B[p] is within right, then i is beautiful
            if p < len(B) and B[p] <= right:
                ans.append(i)

        return ans
