class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_occurrences(text: str, pat: str) -> List[int]:
            # KMP to find all start indices where pat occurs in text
            n, m = len(text), len(pat)
            if m == 0:
                return list(range(n + 1))

            # build LPS (longest prefix suffix) array
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            # search
            res = []
            j = 0
            for i in range(n):
                while j > 0 and text[i] != pat[j]:
                    j = lps[j - 1]
                if text[i] == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = lps[j - 1]
            return res

        A = find_occurrences(s, a)
        B = find_occurrences(s, b)

        ans = []
        if not B:
            return ans

        # Two pointers: for each i in A, check if there's some j in B with |j-i| <= k
        p = 0
        for i in A:
            while p < len(B) and B[p] < i - k:
                p += 1
            if p < len(B) and abs(B[p] - i) <= k:
                ans.append(i)

        return ans
