import sys

def solve() -> None:
    sys.setrecursionlimit(1_000_000)
    input = sys.stdin.readline

    N, M = map(int, input().split())
    edges = [[] for _ in range(N + 1)]
    for _ in range(M):
        u, v, b, c = map(int, input().split())
        edges[u].append((v, b, c))

    # Feasibility check for a given ratio x:
    # Define edge weight w = b - x*c.
    # There exists a path 1->N with (sum b)/(sum c) >= x  <=>  max_path_sum_w >= 0.
    # Graph is a DAG due to u < v, so we can do DP in topological order (1..N).
    def feasible(x: float) -> bool:
        neg_inf = -1e100
        dp = [neg_inf] * (N + 1)
        dp[1] = 0.0
        for u in range(1, N + 1):
            du = dp[u]
            if du <= neg_inf / 2:
                continue
            for v, b, c in edges[u]:
                val = du + (b - x * c)
                if val > dp[v]:
                    dp[v] = val
        return dp[N] >= 0.0

    # Upper bound on answer: max (b/c) over edges (path ratio can't exceed max edge ratio).
    hi = 0.0
    for u in range(1, N + 1):
        for v, b, c in edges[u]:
            r = b / c
            if r > hi:
                hi = r
    lo = 0.0

    # Binary search with enough iterations for 1e-9 accuracy.
    for _ in range(80):
        mid = (lo + hi) / 2.0
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(f"{lo:.16f}")

if __name__ == "__main__":
    solve()
