import sys
sys.setrecursionlimit(1_000_000)

def main():
    A = [list(map(int, sys.stdin.readline().split())) for _ in range(3)]
    vals = [A[i][j] for i in range(3) for j in range(3)]

    # All winning lines in 3x3 (indices 0..8)
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),  # rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8),  # cols
        (0, 4, 8), (2, 4, 6)              # diagonals
    ]

    # memo[(r_mask, b_mask, turn)] -> winner (True for Takahashi, False for Aoki)
    memo = {}

    def has_three(mask: int) -> bool:
        for a, b, c in lines:
            bit_a = 1 << a
            bit_b = 1 << b
            bit_c = 1 << c
            if (mask & bit_a) and (mask & bit_b) and (mask & bit_c):
                return True
        return False

    def dfs(rmask: int, bmask: int, turn: int) -> bool:
        """
        Returns True if Takahashi wins from this state with optimal play, else False.
        turn: 0 = Takahashi to move, 1 = Aoki to move
        """
        key = (rmask, bmask, turn)
        if key in memo:
            return memo[key]

        # If someone already has three, the game would have ended earlier.
        if has_three(rmask):
            memo[key] = True
            return True
        if has_three(bmask):
            memo[key] = False
            return False

        used = rmask | bmask
        if used == (1 << 9) - 1:
            # No empty cells; decide by score
            t_score = 0
            a_score = 0
            for i in range(9):
                if (rmask >> i) & 1:
                    t_score += vals[i]
                elif (bmask >> i) & 1:
                    a_score += vals[i]
            memo[key] = (t_score > a_score)  # no ties since total sum is odd
            return memo[key]

        if turn == 0:
            # Takahashi tries to find a move that makes him win
            for i in range(9):
                if (used >> i) & 1:
                    continue
                nr = rmask | (1 << i)
                if has_three(nr):
                    memo[key] = True
                    return True
                if dfs(nr, bmask, 1):
                    memo[key] = True
                    return True
            memo[key] = False
            return False
        else:
            # Aoki tries to find a move that makes Takahashi lose
            for i in range(9):
                if (used >> i) & 1:
                    continue
                nb = bmask | (1 << i)
                if has_three(nb):
                    memo[key] = False
                    return False
                if not dfs(rmask, nb, 0):
                    memo[key] = False
                    return False
            memo[key] = True
            return True

    print("Takahashi" if dfs(0, 0, 0) else "Aoki")

if __name__ == "__main__":
    main()
